var n=`0899-mas-huni`;var s=`world-0899`;var t=`MV`;var a=`south-asia`;var d=4;var o=21;var c={en:`Mas Huni`,ua:`Мас гуні`};var r={en:`Mas Huni is a Maldives dish made with canned tuna, red onion, bird's eye chili, desiccated coconut. This home-scale recipe assigns measured ingredients to the steps where they are used. Canned tuna replaces smoked or cured Maldivian fish; this is a simplified mas huni.`,ua:`Мас гуні, страва кухні країни Мальдіви. Основні складники: консервований тунець, червона цибуля, перець чилі пташине око, кокосова стружка. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Консервований тунець замінює мальдівську копчену чи в’ялену рибу; це спрощений мас гуні.`};var u=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`canned-tuna`,340,`g`],[`red-onion`,170,`g`],[`bird-s-eye-chili`,2,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`desiccated-coconut`,175,`g`],[`lime-juice`,55,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`chapati`,4,`pcs`]]}];var h={slug:n,id:s,country:`MV`,region:a,servings:4,minutes:21,title:c,text:r,steps:u};export{t as country,h as default,s as id,o as minutes,a as region,d as servings,n as slug,u as steps,r as text,c as title};